structure.syntax:
githubActionsStorageInputSchema = {
    type: 'object',
    required: ['repo', 'operation'],
    additionalProperties: false,
    properties: {
        repo: { type: 'string', minLength: 3, maxLength: 256, pattern: '^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$', description: 'Repository in owner/repo form.' },
        operation: { type: 'string', enum: ['inspect', 'delete_artifacts', 'delete_caches', 'set_retention'], description: 'Exact storage administration operation.' },
        artifact_ids: { type: 'array', minItems: 1, maxItems: 1000, uniqueItems: true, items: { type: 'integer', minimum: 1 }, description: 'Exact GitHub artifact IDs to delete. Required only for delete_artifacts.' },
        cache_ids: { type: 'array', minItems: 1, maxItems: 1000, uniqueItems: true, items: { type: 'integer', minimum: 1 }, description: 'Exact GitHub Actions cache IDs to delete. Required only for delete_caches.' },
        days: { type: 'integer', minimum: 1, maximum: 400, description: 'Artifact/log retention days. Required only for set_retention.' },
        run_id: { type: 'string', minLength: 1, maxLength: 512, description: 'Optional orchestration run token used only for correlation.' },
    },
}

requiredCheckObservationPolicy = Object.freeze({
    minimum_observations: 3,
    minimum_age_ms: 15000,
})

projectTransitionLeasePersistence = Object.freeze({
    idempotency_prefix: IDEMPOTENCY_PREFIX,
    settle_idempotency_prefix: SETTLE_IDEMPOTENCY_PREFIX,
    storage_scope: STORAGE_SCOPE,
})

input_schema.syntax:
Object.freeze({
    type: 'object',
    required: ['repo', 'pull_request', 'expected_head'],
    additionalProperties: false,
    properties: {
        repo: { type: 'string', minLength: 3, maxLength: 256, pattern: '^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$', description: 'Repository in owner/repo form.' },
        pull_request: { type: 'integer', minimum: 1, description: 'Open pull request number.' },
        expected_head: { type: 'string', pattern: '^[0-9a-fA-F]{40}$', description: 'Exact current pull request head SHA. Any movement invalidates the request.' },
        run_id: { type: 'string', minLength: 1, maxLength: 512, description: 'Optional orchestration run id used only for correlation.' },
    },
})

Object.freeze({
    type: 'object',
    required: ['run_id'],
    properties: {
        run_id: { type: 'string', minLength: 1, maxLength: 512 },
        work_ref: { type: 'string', minLength: 1, maxLength: 128 },
    },
    additionalProperties: false,
})

Object.freeze({
    type: 'object',
    required: ['repo'],
    properties: {
        repo: { type: 'string', minLength: 3, maxLength: 256, pattern: '^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$' },
    },
    additionalProperties: false,
})

Object.freeze({
    type: 'object',
    required: ['project_ref'],
    properties: {
        project_ref: { type: 'string', pattern: '^github:[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$' },
        transition_id: { type: 'string', minLength: 1, maxLength: 256, pattern: '^\\S+$' },
        resume_ref: { type: 'string', minLength: 1, maxLength: 512, pattern: '^\\S+$' },
        execution_result: {
            type: 'object',
            required: ['disposition'],
            properties: {
                disposition: { type: 'string', enum: [...WORK_SETTLEMENT_DISPOSITIONS] },
                evidence: { type: 'array', items: { type: 'object', required: ['kind', 'ref'], properties: { kind: { type: 'string' }, ref: { type: 'string' } }, additionalProperties: false } },
                reason: { type: ['string', 'null'] },
            },
            additionalProperties: false,
        },
    },
    additionalProperties: false,
})

Object.freeze({
    type: 'object',
    required: ['project_ref', 'expected_revision', 'amendment'],
    properties: {
        project_ref: { type: 'string', pattern: '^github:[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$' },
        expected_revision: { type: 'string', pattern: '^[0-9a-fA-F]{40}$' },
        amendment: { type: 'object' },
    },
    additionalProperties: false,
})

Object.freeze({
    type: 'object',
    required: ['project_ref', 'expected_revision', 'definition'],
    properties: {
        project_ref: { type: 'string', pattern: '^github:[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$' },
        expected_revision: { type: 'string', pattern: '^[0-9a-fA-F]{40}$' },
        definition: { type: 'object' },
    },
    additionalProperties: false,
})

Object.freeze({
    type: 'object',
    required: ['project_ref'],
    properties: {
        project_ref: { type: 'string', pattern: '^github:[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$' },
    },
    additionalProperties: false,
})

Object.freeze({
    type: 'object',
    required: ['plan', 'body'],
    properties: {
        plan: { type: 'object' },
        body: { type: 'string', maxLength: 125000 },
    },
    additionalProperties: false,
})

